diff --git a/frontend/src/features/chat/model/run-trace-projection.ts b/frontend/src/features/chat/model/run-trace-projection.ts
new file mode 100644
index 0000000..ee9a7d3
--- /dev/null
+++ b/frontend/src/features/chat/model/run-trace-projection.ts
@@ -0,0 +1,357 @@
+import { A2UI_PROFILE, A2UI_VERSION, validateA2uiMessage } from "@/features/a2ui/a2ui-protocol";
+import {
+  EMPTY_A2UI_PROCESSOR_STATE,
+  reduceA2uiMessage,
+} from "@/features/a2ui/a2ui-surface-processor";
+import type {
+  PersistedRunEvent,
+  PersistedRunEventKind,
+} from "@/platform/pglite/run-event-repository";
+import { phaseOfAguiEvent } from "@/platform/agui/agui-normalizer";
+import type { UarAguiEvent } from "@/platform/agui/agui-schema";
+import {
+  RUN_TRACE_PHASES,
+  type RunEventTiming,
+  type RunReplayPatchOperation,
+  type RunReplayProjection,
+  type RunTraceEventNode,
+  type RunTraceFilters,
+  type RunTracePhase,
+  type RunTracePhaseNode,
+  type RunTraceProjection,
+  type RunTraceProjectionInput,
+  type RunTraceRootNode,
+  type RunTraceSegment,
+  type RunTraceTreeNode,
+  type VisibleTraceRow,
+} from "@/features/chat/model/run-trace-types";
+
+const EVENT_KINDS: readonly PersistedRunEventKind[] = [
+  "lifecycle",
+  "message",
+  "reasoning",
+  "tool",
+  "state",
+  "custom",
+  "raw",
+];
+
+const SURFACE_PATH = /^\/a2ui\/surfaces\/([^/]+)(?:\/(components|dataModel))?$/;
+
+export const DEFAULT_RUN_TRACE_FILTERS: RunTraceFilters = {
+  lifecycle: true,
+  message: true,
+  reasoning: true,
+  tool: true,
+  state: true,
+  custom: true,
+  raw: true,
+};
+
+interface SpanStart {
+  eventId: string;
+  atMs: number;
+}
+
+function phaseOfEvent(event: PersistedRunEvent): RunTracePhase {
+  const payload = {
+    ...event.payload,
+    type: event.type,
+    eventId: event.eventId,
+    sequence: event.wireSequence,
+    profile: "uar.agui/1",
+  } as UarAguiEvent;
+  return phaseOfAguiEvent(payload) ?? "lifecycle";
+}
+
+function eventLabel(event: PersistedRunEvent): string {
+  const summary = event.payload.name ?? event.payload.messageId ?? event.payload.toolCallId;
+  return typeof summary === "string" && summary.length > 0
+    ? `${event.type} · ${summary}`
+    : event.type;
+}
+
+function messageIdentity(event: PersistedRunEvent): string | null {
+  const value = event.payload.messageId ?? event.payload.message_id;
+  return typeof value === "string" && value.length > 0 ? value : null;
+}
+
+function correlation(event: PersistedRunEvent): { action: "start" | "end"; key: string } | null {
+  const type = event.type;
+  const payload = event.payload;
+  const id = (...keys: string[]): string => {
+    for (const key of keys) {
+      const value = payload[key];
+      if (typeof value === "string" && value.length > 0) return value;
+    }
+    return event.runId;
+  };
+
+  if (type === "RUN_STARTED") return { action: "start", key: `run:${event.runId}` };
+  if (type === "RUN_FINISHED" || type === "RUN_ERROR") {
+    return { action: "end", key: `run:${event.runId}` };
+  }
+  if (type === "STEP_STARTED") return { action: "start", key: `step:${id("stepId", "stepName", "name")}` };
+  if (type === "STEP_FINISHED") return { action: "end", key: `step:${id("stepId", "stepName", "name")}` };
+  if (type === "TEXT_MESSAGE_START") return { action: "start", key: `message:${id("messageId", "message_id")}` };
+  if (type === "TEXT_MESSAGE_END") return { action: "end", key: `message:${id("messageId", "message_id")}` };
+  if (type === "REASONING_START") return { action: "start", key: `reasoning:${event.runId}` };
+  if (type === "REASONING_END") return { action: "end", key: `reasoning:${event.runId}` };
+  if (type === "REASONING_MESSAGE_START") return { action: "start", key: `reasoning-message:${id("messageId", "message_id")}` };
+  if (type === "REASONING_MESSAGE_END") return { action: "end", key: `reasoning-message:${id("messageId", "message_id")}` };
+  if (type === "TOOL_CALL_START") return { action: "start", key: `tool:${id("toolCallId", "tool_call_id")}` };
+  if (type === "TOOL_CALL_END" || type === "TOOL_CALL_RESULT") {
+    return { action: "end", key: `tool:${id("toolCallId", "tool_call_id")}` };
+  }
+  return null;
+}
+
+function explicitDuration(event: PersistedRunEvent): number | null {
+  const value = event.payload.durationMs ?? event.payload.duration_ms;
+  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : null;
+}
+
+function buildTimings(events: PersistedRunEvent[]): Map<string, RunEventTiming> {
+  const timings = new Map<string, RunEventTiming>();
+  const openSpans = new Map<string, SpanStart>();
+  let precedingAtMs: number | null = null;
+
+  for (const event of events) {
+    const atMs = Date.parse(event.at);
+    const explicit = explicitDuration(event);
+    timings.set(event.eventId, {
+      start: event.at,
+      gapMs: precedingAtMs === null || !Number.isFinite(atMs)
+        ? 0
+        : Math.max(0, atMs - precedingAtMs),
+      durationMs: explicit,
+      durationSource: explicit === null ? "instant" : "explicit",
+    });
+    if (Number.isFinite(atMs)) precedingAtMs = atMs;
+
+    const span = correlation(event);
+    if (!span || !Number.isFinite(atMs)) continue;
+    if (span.action === "start") {
+      openSpans.set(span.key, { eventId: event.eventId, atMs });
+      continue;
+    }
+    const start = openSpans.get(span.key);
+    if (!start) continue;
+    openSpans.delete(span.key);
+    const startTiming = timings.get(start.eventId);
+    if (startTiming?.durationSource === "instant") {
+      timings.set(start.eventId, {
+        ...startTiming,
+        durationMs: Math.max(0, atMs - start.atMs),
+        durationSource: "correlated",
+      });
+    }
+  }
+  return timings;
+}
+
+export function buildRunTraceSegments(
+  timings: Record<string, number>,
+): RunTraceSegment[] {
+  const present = RUN_TRACE_PHASES
+    .map((phase) => ({ phase, durationMs: Math.max(0, Number(timings[phase] ?? 0)) }))
+    .filter((entry) => entry.durationMs > 0);
+  const total = present.reduce((sum, entry) => sum + entry.durationMs, 0);
+  return present.map((entry) => {
+    const exactPercentage = total === 0 ? 0 : (entry.durationMs / total) * 100;
+    return {
+      ...entry,
+      exactPercentage,
+      visualWeight: Math.max(3, exactPercentage),
+    };
+  });
+}
+
+function flattenVisibleRows(
+  root: RunTraceRootNode,
+  nodesById: Map<string, RunTraceTreeNode>,
+  expandedNodeIds: ReadonlySet<string>,
+): VisibleTraceRow[] {
+  const rows: VisibleTraceRow[] = [];
+
+  const appendChildren = (parent: RunTraceRootNode | RunTracePhaseNode, depth: number): void => {
+    const setSize = parent.childIds.length;
+    for (const [index, childId] of parent.childIds.entries()) {
+      const node = nodesById.get(childId);
+      if (!node) continue;
+      const expandable = node.type !== "event" && node.childIds.length > 0;
+      const expanded = expandable && expandedNodeIds.has(node.id);
+      rows.push({
+        id: node.id,
+        node,
+        depth,
+        parentId: parent.id,
+        positionInSet: index + 1,
+        setSize,
+        expandable,
+        expanded,
+      });
+      if (node.type === "phase" && expanded) appendChildren(node, depth + 1);
+    }
+  };
+
+  rows.push({
+    id: root.id,
+    node: root,
+    depth: 1,
+    parentId: null,
+    positionInSet: 1,
+    setSize: 1,
+    expandable: root.childIds.length > 0,
+    expanded: expandedNodeIds.has(root.id),
+  });
+  if (expandedNodeIds.has(root.id)) appendChildren(root, 2);
+  return rows;
+}
+
+export function projectRunTrace(input: RunTraceProjectionInput): RunTraceProjection {
+  const nodesById = new Map<string, RunTraceTreeNode>();
+  const eventsById = new Map<string, PersistedRunEvent>();
+  const messageNodeIds = new Map<string, string[]>();
+  const phaseNodeIds = new Map<RunTracePhase, string>();
+  const phaseNodes = new Map<RunTracePhase, RunTracePhaseNode>();
+  const countsByKind = Object.fromEntries(EVENT_KINDS.map((kind) => [kind, 0])) as Record<
+    PersistedRunEventKind,
+    number
+  >;
+  const timingsByEventId = buildTimings(input.events);
+
+  if (!input.run) {
+    return {
+      rootId: null,
+      nodesById,
+      visibleRows: [],
+      countsByKind,
+      timingsByEventId,
+      eventsById,
+      messageNodeIds,
+      phaseNodeIds,
+      segments: [],
+      selectedNodeId: null,
+    };
+  }
+
+  const rootId = `run:${input.run.id}`;
+  const root: RunTraceRootNode = {
+    id: rootId,
+    parentId: null,
+    type: "run",
+    label: `Run ${input.run.id}`,
+    run: input.run,
+    childIds: [],
+  };
+  nodesById.set(rootId, root);
+
+  for (const event of input.events) {
+    countsByKind[event.kind] += 1;
+    eventsById.set(event.eventId, event);
+    if (!input.filters[event.kind]) continue;
+
+    const phase = phaseOfEvent(event);
+    let phaseNode = phaseNodes.get(phase);
+    if (!phaseNode) {
+      const phaseId = `phase:${phase}`;
+      phaseNode = {
+        id: phaseId,
+        parentId: rootId,
+        type: "phase",
+        phase,
+        label: phase,
+        childIds: [],
+      };
+      phaseNodes.set(phase, phaseNode);
+      phaseNodeIds.set(phase, phaseId);
+      root.childIds.push(phaseId);
+      nodesById.set(phaseId, phaseNode);
+    }
+
+    const eventNodeId = `event:${event.eventId}`;
+    const eventNode: RunTraceEventNode = {
+      id: eventNodeId,
+      parentId: phaseNode.id,
+      type: "event",
+      phase,
+      label: eventLabel(event),
+      event,
+    };
+    phaseNode.childIds.push(eventNodeId);
+    nodesById.set(eventNodeId, eventNode);
+
+    const messageId = messageIdentity(event);
+    if (messageId) {
+      const current = messageNodeIds.get(messageId) ?? [];
+      current.push(eventNodeId);
+      messageNodeIds.set(messageId, current);
+    }
+  }
+
+  const visibleRows = flattenVisibleRows(root, nodesById, input.expandedNodeIds);
+  const selectedNodeId = input.selectedNodeId && visibleRows.some((row) => row.id === input.selectedNodeId)
+    ? input.selectedNodeId
+    : visibleRows.find((row) => row.node.type === "event")?.id ?? visibleRows[0]?.id ?? null;
+
+  return {
+    rootId,
+    nodesById,
+    visibleRows,
+    countsByKind,
+    timingsByEventId,
+    eventsById,
+    messageNodeIds,
+    phaseNodeIds,
+    segments: buildRunTraceSegments(input.run.phaseTimings),
+    selectedNodeId,
+  };
+}
+
+function replayEnvelope(operation: RunReplayPatchOperation): unknown {
+  const match = SURFACE_PATH.exec(operation.path);
+  if (!match) throw new Error(`Invalid A2UI replay path: ${operation.path}`);
+  const surfaceId = match[1];
+  const suffix = match[2];
+  const base = { version: A2UI_VERSION, profile: A2UI_PROFILE };
+
+  if (operation.op === "add" && suffix === undefined) {
+    return {
+      ...base,
+      createSurface: { surfaceId, ...(operation.value as Record<string, unknown>) },
+    };
+  }
+  if (operation.op === "replace" && suffix === "components") {
+    return {
+      ...base,
+      updateComponents: { surfaceId, ...(operation.value as Record<string, unknown>) },
+    };
+  }
+  if (operation.op === "replace" && suffix === "dataModel") {
+    return {
+      ...base,
+      updateDataModel: { surfaceId, ...(operation.value as Record<string, unknown>) },
+    };
+  }
+  if (operation.op === "remove" && suffix === undefined) {
+    return { ...base, deleteSurface: { surfaceId } };
+  }
+  throw new Error(`Unsupported A2UI replay operation: ${operation.op} ${operation.path}`);
+}
+
+export function projectA2uiReplay(
+  operations: RunReplayPatchOperation[],
+): RunReplayProjection {
+  let state = EMPTY_A2UI_PROCESSOR_STATE;
+  for (const [index, operation] of operations.entries()) {
+    const envelope = replayEnvelope(operation);
+    const validation = validateA2uiMessage(envelope);
+    if (!validation.success) {
+      throw new Error(`Invalid A2UI replay operation ${index}: ${validation.error}`);
+    }
+    state = reduceA2uiMessage(state, validation.data);
+    if (state.error) throw new Error(`Invalid A2UI replay operation ${index}: ${state.error}`);
+  }
+  return { state, appliedOperations: operations.length };
+}
diff --git a/frontend/src/features/chat/model/run-trace-store.ts b/frontend/src/features/chat/model/run-trace-store.ts
new file mode 100644
index 0000000..7380b36
--- /dev/null
+++ b/frontend/src/features/chat/model/run-trace-store.ts
@@ -0,0 +1,338 @@
+import { create } from "zustand";
+
+import {
+  fetchRunCheckpoints,
+  fetchRunSurfaceReplay,
+  resolveRuntimeAgentArtifact,
+  resumeRunFromLatestCheckpoint,
+  subscribeRunTraceSnapshot,
+} from "@/features/chat/api/run-trace-api";
+import {
+  DEFAULT_RUN_TRACE_FILTERS,
+  projectA2uiReplay,
+  projectRunTrace,
+} from "@/features/chat/model/run-trace-projection";
+import type {
+  ResumeRunResponse,
+  RunCheckpoint,
+  RunReplayProjection,
+  RunTraceContext,
+  RunTraceFilters,
+  RunTraceNetworkState,
+  RunTracePhase,
+  RunTraceProjection,
+  RuntimeAgentArtifact,
+} from "@/features/chat/model/run-trace-types";
+import type {
+  PersistedRunEventKind,
+  PersistedRunSnapshot,
+  PersistedRunSnapshotSubscription,
+} from "@/platform/pglite/run-event-repository";
+
+const EMPTY_SNAPSHOT: PersistedRunSnapshot = { run: null, events: [] };
+const DEFAULT_EXPANSION = new Set([
+  "phase:context",
+  "phase:skill",
+  "phase:memory",
+  "phase:retrieval",
+  "phase:reasoning",
+  "phase:tool",
+  "phase:generate",
+  "phase:lifecycle",
+]);
+
+function idleNetworkState(): RunTraceNetworkState {
+  const idle = { status: "idle" as const, error: null };
+  return {
+    snapshot: { ...idle },
+    checkpoints: { ...idle },
+    replay: { ...idle },
+    agent: { ...idle },
+    resume: { ...idle },
+  };
+}
+
+function errorMessage(error: unknown): string {
+  return error instanceof Error ? error.message : String(error);
+}
+
+function initialProjection(): RunTraceProjection {
+  return projectRunTrace({
+    ...EMPTY_SNAPSHOT,
+    filters: DEFAULT_RUN_TRACE_FILTERS,
+    expandedNodeIds: new Set(),
+    selectedNodeId: null,
+  });
+}
+
+interface RunTraceStoreState {
+  context: RunTraceContext | null;
+  snapshot: PersistedRunSnapshot;
+  projection: RunTraceProjection;
+  filters: RunTraceFilters;
+  expandedNodeIds: Set<string>;
+  selectedNodeId: string | null;
+  selectedCheckpointId: string | null;
+  checkpoints: RunCheckpoint[];
+  replay: RunReplayProjection | null;
+  agentArtifact: RuntimeAgentArtifact | null;
+  resumedRunId: string | null;
+  network: RunTraceNetworkState;
+  subscription: PersistedRunSnapshotSubscription | null;
+  generation: number;
+  selectContext: (context: RunTraceContext | null) => Promise<void>;
+  toggleFilter: (kind: PersistedRunEventKind) => void;
+  toggleExpanded: (nodeId: string) => void;
+  selectNode: (nodeId: string) => void;
+  selectPhase: (phase: RunTracePhase) => string | null;
+  selectCheckpoint: (checkpointId: string | null) => void;
+  refreshCheckpoints: () => Promise<void>;
+  refreshReplay: () => Promise<void>;
+  refreshAgentArtifact: () => Promise<void>;
+  resumeLatestCheckpoint: (input?: string) => Promise<ResumeRunResponse | null>;
+  dispose: () => Promise<void>;
+}
+
+function reproject(
+  state: Pick<RunTraceStoreState, "snapshot" | "filters" | "expandedNodeIds" | "selectedNodeId">,
+): Pick<RunTraceStoreState, "projection" | "selectedNodeId"> {
+  const projection = projectRunTrace({
+    ...state.snapshot,
+    filters: state.filters,
+    expandedNodeIds: state.expandedNodeIds,
+    selectedNodeId: state.selectedNodeId,
+  });
+  return { projection, selectedNodeId: projection.selectedNodeId };
+}
+
+export const useRunTraceStore = create<RunTraceStoreState>((set, get) => ({
+  context: null,
+  snapshot: EMPTY_SNAPSHOT,
+  projection: initialProjection(),
+  filters: { ...DEFAULT_RUN_TRACE_FILTERS },
+  expandedNodeIds: new Set(),
+  selectedNodeId: null,
+  selectedCheckpointId: null,
+  checkpoints: [],
+  replay: null,
+  agentArtifact: null,
+  resumedRunId: null,
+  network: idleNetworkState(),
+  subscription: null,
+  generation: 0,
+
+  selectContext: async (context) => {
+    const generation = get().generation + 1;
+    const previousSubscription = get().subscription;
+    set({ generation, subscription: null });
+    await previousSubscription?.unsubscribe();
+
+    if (get().generation !== generation) return;
+    if (!context) {
+      set({
+        context: null,
+        snapshot: EMPTY_SNAPSHOT,
+        projection: initialProjection(),
+        filters: { ...DEFAULT_RUN_TRACE_FILTERS },
+        expandedNodeIds: new Set(),
+        selectedNodeId: null,
+        selectedCheckpointId: null,
+        checkpoints: [],
+        replay: null,
+        agentArtifact: null,
+        resumedRunId: null,
+        network: idleNetworkState(),
+      });
+      return;
+    }
+
+    const expandedNodeIds = new Set(DEFAULT_EXPANSION);
+    expandedNodeIds.add(`run:${context.runId}`);
+    set({
+      context,
+      snapshot: EMPTY_SNAPSHOT,
+      projection: initialProjection(),
+      filters: { ...DEFAULT_RUN_TRACE_FILTERS },
+      expandedNodeIds,
+      selectedNodeId: null,
+      selectedCheckpointId: null,
+      checkpoints: [],
+      replay: null,
+      agentArtifact: null,
+      resumedRunId: null,
+      network: {
+        ...idleNetworkState(),
+        snapshot: { status: "loading", error: null },
+      },
+    });
+
+    const onSnapshot = (snapshot: PersistedRunSnapshot): void => {
+      const current = get();
+      if (current.generation !== generation || current.context?.runId !== context.runId) return;
+      const next = { ...current, snapshot };
+      set({ snapshot, ...reproject(next) });
+    };
+    try {
+      const subscription = await subscribeRunTraceSnapshot(context.runId, onSnapshot);
+      if (get().generation !== generation || get().context?.runId !== context.runId) {
+        await subscription.unsubscribe();
+        return;
+      }
+      set((state) => ({
+        subscription,
+        network: { ...state.network, snapshot: { status: "success", error: null } },
+      }));
+      if (get().snapshot.run === null) onSnapshot(subscription.initialSnapshot);
+    } catch (error) {
+      if (get().generation !== generation || get().context?.runId !== context.runId) return;
+      set((state) => ({
+        network: {
+          ...state.network,
+          snapshot: { status: "error", error: errorMessage(error) },
+        },
+      }));
+    }
+
+    void get().refreshCheckpoints();
+    void get().refreshReplay();
+    if (context.agentId) void get().refreshAgentArtifact();
+  },
+
+  toggleFilter: (kind) => {
+    const current = get();
+    const filters = { ...current.filters, [kind]: !current.filters[kind] };
+    set({ filters, ...reproject({ ...current, filters }) });
+  },
+
+  toggleExpanded: (nodeId) => {
+    const current = get();
+    const expandedNodeIds = new Set(current.expandedNodeIds);
+    if (expandedNodeIds.has(nodeId)) expandedNodeIds.delete(nodeId);
+    else expandedNodeIds.add(nodeId);
+    set({ expandedNodeIds, ...reproject({ ...current, expandedNodeIds }) });
+  },
+
+  selectNode: (nodeId) => {
+    const current = get();
+    if (!current.projection.nodesById.has(nodeId)) return;
+    set(reproject({ ...current, selectedNodeId: nodeId }));
+  },
+
+  selectPhase: (phase) => {
+    const current = get();
+    const nodeId = current.projection.phaseNodeIds.get(phase) ?? null;
+    if (!nodeId) return null;
+    const expandedNodeIds = new Set(current.expandedNodeIds);
+    if (current.projection.rootId) expandedNodeIds.add(current.projection.rootId);
+    expandedNodeIds.add(nodeId);
+    set({
+      expandedNodeIds,
+      ...reproject({ ...current, expandedNodeIds, selectedNodeId: nodeId }),
+    });
+    return nodeId;
+  },
+
+  selectCheckpoint: (checkpointId) => set({ selectedCheckpointId: checkpointId }),
+
+  refreshCheckpoints: async () => {
+    const context = get().context;
+    if (!context) return;
+    set((state) => ({
+      network: { ...state.network, checkpoints: { status: "loading", error: null } },
+    }));
+    try {
+      const response = await fetchRunCheckpoints(context.runId);
+      if (get().context?.runId !== context.runId) return;
+      set((state) => ({
+        checkpoints: response.checkpoints,
+        selectedCheckpointId: response.checkpoints.some(
+          (checkpoint) => checkpoint.id === state.selectedCheckpointId,
+        ) ? state.selectedCheckpointId : response.checkpoints.at(-1)?.id ?? null,
+        network: { ...state.network, checkpoints: { status: "success", error: null } },
+      }));
+    } catch (error) {
+      if (get().context?.runId !== context.runId) return;
+      set((state) => ({
+        network: {
+          ...state.network,
+          checkpoints: { status: "error", error: errorMessage(error) },
+        },
+      }));
+    }
+  },
+
+  refreshReplay: async () => {
+    const context = get().context;
+    if (!context) return;
+    set((state) => ({
+      network: { ...state.network, replay: { status: "loading", error: null } },
+    }));
+    try {
+      const replay = projectA2uiReplay(await fetchRunSurfaceReplay(context.runId));
+      if (get().context?.runId !== context.runId) return;
+      set((state) => ({
+        replay,
+        network: { ...state.network, replay: { status: "success", error: null } },
+      }));
+    } catch (error) {
+      if (get().context?.runId !== context.runId) return;
+      set((state) => ({
+        network: { ...state.network, replay: { status: "error", error: errorMessage(error) } },
+      }));
+    }
+  },
+
+  refreshAgentArtifact: async () => {
+    const context = get().context;
+    if (!context?.agentId) return;
+    set((state) => ({
+      network: { ...state.network, agent: { status: "loading", error: null } },
+    }));
+    try {
+      const agentArtifact = await resolveRuntimeAgentArtifact(context.agentId);
+      if (get().context?.runId !== context.runId) return;
+      set((state) => ({
+        agentArtifact,
+        network: { ...state.network, agent: { status: "success", error: null } },
+      }));
+    } catch (error) {
+      if (get().context?.runId !== context.runId) return;
+      set((state) => ({
+        network: { ...state.network, agent: { status: "error", error: errorMessage(error) } },
+      }));
+    }
+  },
+
+  resumeLatestCheckpoint: async (input) => {
+    const current = get();
+    if (!current.context || !current.agentArtifact || current.checkpoints.length === 0) return null;
+    set((state) => ({
+      network: { ...state.network, resume: { status: "loading", error: null } },
+    }));
+    try {
+      const response = await resumeRunFromLatestCheckpoint(current.context.runId, {
+        artifact: current.agentArtifact,
+        ...(input ? { input } : {}),
+        ...(current.context.sessionId ? { session_id: current.context.sessionId } : {}),
+      });
+      if (get().context?.runId !== current.context.runId) return null;
+      set((state) => ({
+        resumedRunId: response.run_id,
+        network: { ...state.network, resume: { status: "success", error: null } },
+      }));
+      return response;
+    } catch (error) {
+      if (get().context?.runId !== current.context.runId) return null;
+      set((state) => ({
+        network: { ...state.network, resume: { status: "error", error: errorMessage(error) } },
+      }));
+      return null;
+    }
+  },
+
+  dispose: async () => {
+    const subscription = get().subscription;
+    set((state) => ({ generation: state.generation + 1, subscription: null }));
+    await subscription?.unsubscribe();
+  },
+}));
