+      expect(canvas.getByRole("treeitem", { selected: true })).toHaveTextContent("#450");
+    });
+    const mountedRows = canvas.getAllByRole("treeitem");
+    expect(tree).toHaveAttribute("data-virtualized", "true");
+    expect(tree.getBoundingClientRect().height).toBeLessThan(1000);
+    expect(tree.clientHeight).toBeLessThan(1000);
+    expect(Number(tree.dataset.mountedCount)).toBeLessThan(40);
+    expect(mountedRows.length).toBeLessThan(40);
+    expect(mountedRows.some((row) => row.getAttribute("aria-setsize") === "500")).toBe(true);
+    expect(Number(root.dataset.mountMs)).toBeLessThan(100);
+  },
+};
diff --git a/frontend/src/platform/pglite/client.ts b/frontend/src/platform/pglite/client.ts
new file mode 100644
index 0000000..22bdbe1
--- /dev/null
+++ b/frontend/src/platform/pglite/client.ts
@@ -0,0 +1,321 @@
+import { PGlite } from "@electric-sql/pglite";
+import { live, type PGliteWithLive } from "@electric-sql/pglite/live";
+import type { ContentBlock, RichMessage } from "@/types/chat-content";
+import type { LocalThread } from "@/types";
+import { loadPgliteFsBundle } from "@/platform/pglite/assets";
+import { MIGRATIONS } from "@/platform/pglite/migrations";
+import {
+  RunEventRepository,
+  type AppendPersistedRunEventInput,
+  type FinishPersistedRunInput,
+  type PersistedRun,
+  type PersistedRunEvent,
+  type PersistedRunSnapshot,
+  type PersistedRunSnapshotSubscription,
+  type StartPersistedRunInput,
+} from "@/platform/pglite/run-event-repository";
+
+// ---------------------------------------------------------------------------
+// Status callback type — emitted during open() for loading-screen feedback
+// ---------------------------------------------------------------------------
+
+export type OnStatusFn = (msg: string) => void;
+
+type UarPGlite = PGlite & PGliteWithLive;
+
+// ---------------------------------------------------------------------------
+// Module-level singleton — set once by DbProvider, consumed by stores
+// ---------------------------------------------------------------------------
+
+let _instance: UarDb | null = null;
+let _openPromise: Promise<UarDb> | null = null;
+
+export function setDbInstance(db: UarDb): void {
+  _instance = db;
+}
+
+/** Returns the initialized UarDb. Throws if called before DbProvider is ready. */
+export function getDbInstance(): UarDb {
+  if (!_instance) throw new Error("[UarDb] Database not yet initialized");
+  return _instance;
+}
+
+// ---------------------------------------------------------------------------
+// Schema migrations
+// ---------------------------------------------------------------------------
+
+// ---------------------------------------------------------------------------
+// Row shapes returned from PGlite queries
+// ---------------------------------------------------------------------------
+
+interface ThreadRow {
+  id: string;
+  title: string;
+  is_ephemeral: boolean;
+  created_at: string;
+  updated_at: string;
+}
+
+interface MessageRow {
+  id: string;
+  thread_id: string;
+  role: "user" | "assistant" | "system";
+  content: ContentBlock[] | string; // PGlite may return JSONB already parsed or as string
+  created_at: string;
+  status: string;
+}
+
+// ---------------------------------------------------------------------------
+// UarDb — thin typed wrapper around PGlite
+// ---------------------------------------------------------------------------
+
+export class UarDb {
+  private readonly runEvents: RunEventRepository;
+
+  private constructor(private readonly db: UarPGlite) {
+    this.runEvents = new RunEventRepository(db);
+  }
+
+  // ---- lifecycle ----------------------------------------------------------
+
+  static async open(onStatus?: OnStatusFn): Promise<UarDb> {
+    if (_instance) return _instance;
+    if (_openPromise) {
+      onStatus?.("Waiting for local database…");
+      return _openPromise;
+    }
+
+    onStatus?.("Opening local database…");
+    _openPromise = (async () => {
+      const fsBundle = await loadPgliteFsBundle();
+      const db = await PGlite.create("idb://uar-threads", {
+        fsBundle,
+        extensions: { live },
+      });
+      const instance = new UarDb(db);
+      await instance.runMigrations(onStatus);
+      await instance.migrateFromLocalStorage(onStatus);
+      onStatus?.("Database ready");
+      _instance = instance;
+      return instance;
+    })().catch((err: unknown) => {
+      _openPromise = null;
+      throw err;
+    });
+
+    return _openPromise;
+  }
+
+  private async runMigrations(onStatus?: OnStatusFn): Promise<void> {
+    onStatus?.("Bootstrapping schema migrations table…");
+    await this.db.exec(`
+      CREATE TABLE IF NOT EXISTS schema_migrations (
+        version    INTEGER     PRIMARY KEY,
+        applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
+      );
+    `);
+
+    for (const m of MIGRATIONS) {
+      const { rows } = await this.db.query<{ version: number }>(
+        "SELECT version FROM schema_migrations WHERE version = $1",
+        [m.version],
+      );
+      if (rows.length === 0) {
+        onStatus?.(`Applying migration ${m.version}: ${m.name}…`);
+        await this.db.exec(m.up);
+        await this.db.query(
+          "INSERT INTO schema_migrations (version) VALUES ($1)",
+          [m.version],
+        );
+        onStatus?.(`Migration ${m.version} applied`);
+      } else {
+        onStatus?.(`Migration ${m.version} (${m.name}) already applied`);
+      }
+    }
+  }
+
+  /** One-time migration of any data that was previously stored in localStorage. */
+  private async migrateFromLocalStorage(onStatus?: OnStatusFn): Promise<void> {
+    const flag = "uar-pglite-migrated-v1";
+    if (localStorage.getItem(flag)) {
+      onStatus?.("No legacy localStorage data to migrate");
+      return;
+    }
+
+    onStatus?.("Migrating legacy data from localStorage…");
+
+    // Migrate thread registry
+    const rawRegistry = localStorage.getItem("uar-thread-registry");
+    if (rawRegistry) {
+      try {
+        const parsed = JSON.parse(rawRegistry) as { state?: { threads?: Record<string, LocalThread> } };
+        const threads = parsed.state?.threads ?? {};
+        const count = Object.keys(threads).length;
+        onStatus?.(`Migrating ${count} legacy thread(s)…`);
+        for (const t of Object.values(threads)) {
+          await this.upsertThread(t).catch(() => { /* skip invalid rows */ });
+        }
+        onStatus?.(`Migrated ${count} thread(s)`);
+      } catch { /* ignore parse errors */ }
+    } else {
+      onStatus?.("No legacy thread registry found");
+    }
+
+    // Migrate message store
+    const rawMessages = localStorage.getItem("uar-chat-messages");
+    if (rawMessages) {
+      try {
+        const parsed = JSON.parse(rawMessages) as { state?: { messagesByThread?: Record<string, RichMessage[]> } };
+        const byThread = parsed.state?.messagesByThread ?? {};
+        const totalMsgs = Object.values(byThread).reduce((n, msgs) => n + msgs.length, 0);
+        onStatus?.(`Migrating ${totalMsgs} legacy message(s)…`);
+        for (const [threadId, msgs] of Object.entries(byThread)) {
+          // Ensure thread exists before inserting messages
+          const exists = await this.db.query<{ id: string }>(
+            "SELECT id FROM threads WHERE id = $1",
+            [threadId],
+          );
+          if (exists.rows.length === 0) continue;
+          for (const msg of msgs) {
+            await this.insertMessage(threadId, msg).catch(() => { /* skip duplicates */ });
+          }
+        }
+        onStatus?.(`Migrated ${totalMsgs} message(s)`);
+      } catch { /* ignore parse errors */ }
+    } else {
+      onStatus?.("No legacy messages found");
+    }
+
+    // Clean up localStorage keys that are now superseded
+    localStorage.removeItem("uar-thread-registry");
+    localStorage.removeItem("uar-chat-messages");
+    localStorage.setItem(flag, "1");
+    onStatus?.("Legacy migration complete — localStorage cleared");
+  }
+
+  // ---- threads ------------------------------------------------------------
+
+  async getThreads(): Promise<LocalThread[]> {
+    const { rows } = await this.db.query<ThreadRow>(
+      "SELECT id, title, is_ephemeral, created_at, updated_at FROM threads ORDER BY updated_at DESC",
+    );
+    return rows.map(rowToThread);
+  }
+
+  async upsertThread(thread: LocalThread): Promise<void> {
+    await this.db.query(
+      `INSERT INTO threads (id, title, is_ephemeral, created_at, updated_at)
+       VALUES ($1, $2, $3, $4, $5)
+       ON CONFLICT (id) DO UPDATE
+         SET title = EXCLUDED.title,
+             is_ephemeral = EXCLUDED.is_ephemeral,
+             updated_at = EXCLUDED.updated_at`,
+      [thread.id, thread.title, thread.isEphemeral, thread.createdAt, thread.updatedAt],
+    );
+  }
+
+  async deleteThread(id: string): Promise<void> {
+    await this.db.query("DELETE FROM threads WHERE id = $1", [id]);
+  }
+
+  async touchThread(id: string): Promise<void> {
+    const now = new Date().toISOString();
+    await this.db.query(
+      "UPDATE threads SET updated_at = $1 WHERE id = $2",
+      [now, id],
+    );
+  }
+
+  // ---- messages -----------------------------------------------------------
+
+  async getMessages(threadId: string): Promise<RichMessage[]> {
+    const { rows } = await this.db.query<MessageRow>(
+      "SELECT id, thread_id, role, content, created_at, status FROM messages WHERE thread_id = $1 ORDER BY created_at ASC",
+      [threadId],
+    );
+    return rows.map(rowToMessage);
+  }
+
+  async insertMessage(threadId: string, msg: RichMessage): Promise<void> {
+    await this.db.query(
+      `INSERT INTO messages (id, thread_id, role, content, created_at, status)
+       VALUES ($1, $2, $3, $4, $5, $6)
+       ON CONFLICT (id) DO UPDATE
+         SET content = EXCLUDED.content,
+             status  = EXCLUDED.status`,
+      [
+        msg.id,
+        threadId,
+        msg.role,
+        JSON.stringify(msg.content),
+        msg.createdAt instanceof Date ? msg.createdAt.toISOString() : msg.createdAt,
+        msg.status ?? "complete",
+      ],
+    );
+  }
+
+  // ---- runs and normalized events ---------------------------------------
+
+  /** Platform-only handle used by PEM's PGlite persistence adapter. */
+  getPersistenceClient(): PGlite {
+    return this.db;
+  }
+
+  startRun(input: StartPersistedRunInput): Promise<void> {
+    return this.runEvents.startRun(input);
+  }
+
+  finishRun(input: FinishPersistedRunInput): Promise<void> {
+    return this.runEvents.finishRun(input);
+  }
+
+  appendRunEvent(input: AppendPersistedRunEventInput): Promise<number | null> {
+    return this.runEvents.appendEvent(input);
+  }
+
+  getRuns(): Promise<PersistedRun[]> {
+    return this.runEvents.getRuns();
+  }
+
+  getRunEvents(runId: string): Promise<PersistedRunEvent[]> {
+    return this.runEvents.getRunEvents(runId);
+  }
+
+  subscribeRunSnapshot(
+    runId: string,
+    onSnapshot: (snapshot: PersistedRunSnapshot) => void,
+  ): Promise<PersistedRunSnapshotSubscription> {
+    return this.runEvents.subscribeRunSnapshot(runId, onSnapshot);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Row → domain type converters
+// ---------------------------------------------------------------------------
+
+function rowToThread(row: ThreadRow): LocalThread {
+  return {
+    id: row.id,
+    title: row.title,
+    isEphemeral: row.is_ephemeral,
+    createdAt: row.created_at,
+    updatedAt: row.updated_at,
+  };
+}
+
+function rowToMessage(row: MessageRow): RichMessage {
+  let content: ContentBlock[];
+  if (typeof row.content === "string") {
+    try { content = JSON.parse(row.content) as ContentBlock[]; }
+    catch { content = []; }
+  } else {
+    content = row.content as ContentBlock[];
+  }
+  return {
+    id: row.id,
+    role: row.role,
+    content,
+    createdAt: new Date(row.created_at),
+    status: (row.status as RichMessage["status"]) ?? "complete",
+  };
+}
diff --git a/frontend/src/platform/pglite/run-event-repository.ts b/frontend/src/platform/pglite/run-event-repository.ts
new file mode 100644
index 0000000..5acf949
--- /dev/null
+++ b/frontend/src/platform/pglite/run-event-repository.ts
@@ -0,0 +1,302 @@
+import type { PGlitePersistenceClient } from "@/platform/entities";
+import type { RunPhaseTimings } from "@/platform/agui/agui-normalizer";
+import type { LiveNamespace } from "@electric-sql/pglite/live";
+
+export type PersistedRunStatus = "running" | "finished" | "error" | "cancelled";
+
+export type PersistedRunEventKind =
+  | "lifecycle"
+  | "message"
+  | "reasoning"
+  | "tool"
+  | "state"
+  | "custom"
+  | "raw";
+
+export interface PersistedRun {
+  id: string;
+  threadId: string;
+  messageId: string | null;
+  status: PersistedRunStatus;
+  startedAt: string;
+  finishedAt: string | null;
+  model: string | null;
+  usage: Record<string, unknown> | null;
+  costUsd: number | null;
+  phaseTimings: RunPhaseTimings | Record<string, never>;
+}
+
+export interface PersistedRunEvent {
+  runId: string;
+  seq: number;
+  eventId: string;
+  wireSequence: number;
+  type: string;
+  kind: PersistedRunEventKind;
+  at: string;
+  payload: Record<string, unknown>;
+}
+
+export interface PersistedRunSnapshot {
+  run: PersistedRun | null;
+  events: PersistedRunEvent[];
+}
+
+export interface PersistedRunSnapshotSubscription {
+  initialSnapshot: PersistedRunSnapshot;
+  unsubscribe: () => Promise<void>;
+}
+
+interface RunEventLiveClient extends PGlitePersistenceClient {
+  readonly live: LiveNamespace;
+}
+
+export interface StartPersistedRunInput {
+  id: string;
+  threadId: string;
+  messageId?: string | null;
+  model?: string | null;
+  startedAt?: string;
+}
+
+export interface FinishPersistedRunInput {
+  id: string;
+  status: Exclude<PersistedRunStatus, "running">;
+  finishedAt: string;
+  phaseTimings?: RunPhaseTimings;
+  usage?: Record<string, unknown> | null;
+  costUsd?: number | null;
+}
+
+export interface AppendPersistedRunEventInput {
+  runId: string;
+  eventId: string;
+  wireSequence: number;
+  type: string;
+  kind: PersistedRunEventKind;
+  at: string;
+  payload: Record<string, unknown>;
+}
+
+interface RunRow {
+  id: string;
+  thread_id: string;
+  message_id: string | null;
+  status: PersistedRunStatus;
+  started_at: string | Date;
+  finished_at: string | Date | null;
+  model: string | null;
+  usage: Record<string, unknown> | string | null;
+  cost_usd: number | string | null;
+  phase_timings: RunPhaseTimings | string;
+}
+
+interface RunEventRow {
+  run_id: string;
+  seq: number | string;
+  event_id: string;
+  wire_sequence: number | string;
+  type: string;
+  kind: PersistedRunEventKind;
+  at: string | Date;
+  payload: Record<string, unknown> | string;
+}
+
+function jsonRecord(value: Record<string, unknown> | string | null): Record<string, unknown> | null {
+  if (value === null) return null;
+  if (typeof value !== "string") return value;
+  try {
+    const parsed = JSON.parse(value) as unknown;
+    return parsed && typeof parsed === "object" && !Array.isArray(parsed)
+      ? parsed as Record<string, unknown>
+      : {};
+  } catch {
+    return {};
+  }
+}
+
+function timestamp(value: string | Date): string {
+  return value instanceof Date ? value.toISOString() : value;
+}
+
+function toRun(row: RunRow): PersistedRun {
+  return {
+    id: row.id,
+    threadId: row.thread_id,
+    messageId: row.message_id,
+    status: row.status,
+    startedAt: timestamp(row.started_at),
+    finishedAt: row.finished_at === null ? null : timestamp(row.finished_at),
+    model: row.model,
+    usage: jsonRecord(row.usage),
+    costUsd: row.cost_usd === null ? null : Number(row.cost_usd),
+    phaseTimings: (jsonRecord(row.phase_timings) ?? {}) as RunPhaseTimings | Record<string, never>,
+  };
+}
+
+function toRunEvent(row: RunEventRow): PersistedRunEvent {
+  return {
+    runId: row.run_id,
+    seq: Number(row.seq),
+    eventId: row.event_id,
+    wireSequence: Number(row.wire_sequence),
+    type: row.type,
+    kind: row.kind,
+    at: timestamp(row.at),
+    payload: jsonRecord(row.payload) ?? {},
+  };
+}
+
+export class RunEventRepository {
+  constructor(private readonly db: RunEventLiveClient) {}
+
+  async startRun(input: StartPersistedRunInput): Promise<void> {
+    await this.db.query(
+      `INSERT INTO run (id, thread_id, message_id, status, started_at, model)
+       VALUES ($1, $2, $3, 'running', $4, $5)
+       ON CONFLICT (id) DO UPDATE
+         SET thread_id = EXCLUDED.thread_id,
+             message_id = COALESCE(run.message_id, EXCLUDED.message_id),
+             model = COALESCE(run.model, EXCLUDED.model)`,
+      [
+        input.id,
+        input.threadId,
+        input.messageId ?? null,
+        input.startedAt ?? new Date().toISOString(),
+        input.model ?? null,
+      ],
+    );
+  }
+
+  async finishRun(input: FinishPersistedRunInput): Promise<void> {
+    await this.db.query(
+      `UPDATE run
+          SET status = $2,
+              finished_at = $3,
+              phase_timings = COALESCE($4::jsonb, phase_timings),
+              usage = COALESCE($5::jsonb, usage),
+              cost_usd = COALESCE($6, cost_usd)
+        WHERE id = $1
+          AND status = 'running'`,
+      [
+        input.id,
+        input.status,
+        input.finishedAt,
+        input.phaseTimings ? JSON.stringify(input.phaseTimings) : null,
+        input.usage ? JSON.stringify(input.usage) : null,
+        input.costUsd ?? null,
+      ],
+    );
+  }
+
+  async appendEvent(input: AppendPersistedRunEventInput): Promise<number | null> {
+    const { rows } = await this.db.query<{ seq: number | string }>(
+      `WITH next_event AS (
+         SELECT COALESCE(MAX(seq), -1) + 1 AS seq
+           FROM run_event
+          WHERE run_id = $1
+       )
+       INSERT INTO run_event
+         (run_id, seq, event_id, wire_sequence, type, kind, at, payload)
+       SELECT $1, next_event.seq, $2, $3, $4, $5, $6, $7::jsonb
+         FROM next_event
+       ON CONFLICT (run_id, event_id) DO NOTHING
+       RETURNING seq`,
+      [
+        input.runId,
+        input.eventId,
+        input.wireSequence,
+        input.type,
+        input.kind,
+        input.at,
+        JSON.stringify(input.payload),
+      ],
+    );
+    return rows[0] ? Number(rows[0].seq) : null;
+  }
+
+  async getRuns(): Promise<PersistedRun[]> {
+    const { rows } = await this.db.query<RunRow>(
+      `SELECT id, thread_id, message_id, status, started_at, finished_at,
+              model, usage, cost_usd, phase_timings
+         FROM run
+        ORDER BY started_at DESC`,
+    );
+    return rows.map(toRun);
+  }
+
+  async getRunEvents(runId: string): Promise<PersistedRunEvent[]> {
+    const { rows } = await this.db.query<RunEventRow>(
+      `SELECT run_id, seq, event_id, wire_sequence, type, kind, at, payload
+         FROM run_event
+        WHERE run_id = $1
+        ORDER BY seq ASC`,
+      [runId],
+    );
+    return rows.map(toRunEvent);
+  }
+
+  async subscribeRunSnapshot(
+    runId: string,
+    onSnapshot: (snapshot: PersistedRunSnapshot) => void,
+  ): Promise<PersistedRunSnapshotSubscription> {
+    let active = true;
+    let runRows: RunRow[] | null = null;
+    let eventRows: RunEventRow[] | null = null;
+
+    const emitSnapshot = (): void => {
+      if (!active || runRows === null || eventRows === null) return;
+      onSnapshot({
+        run: runRows[0] ? toRun(runRows[0]) : null,
+        events: eventRows.map(toRunEvent),
+      });
+    };
+
+    const [runQuery, eventQuery] = await Promise.all([
+      this.db.live.query<RunRow>(
+        `SELECT id, thread_id, message_id, status, started_at, finished_at,
+                model, usage, cost_usd, phase_timings
+           FROM run
+          WHERE id = $1`,
+        [runId],
+        (results) => {
+          runRows = results.rows;
+          emitSnapshot();
+        },
+      ),
+      this.db.live.query<RunEventRow>(
+        `SELECT run_id, seq, event_id, wire_sequence, type, kind, at, payload
+           FROM run_event
+          WHERE run_id = $1
+          ORDER BY seq ASC`,
+        [runId],
+        (results) => {
+          eventRows = results.rows;
+          emitSnapshot();
+        },
+      ),
+    ]);
+
+    const initialSnapshot = {
+      run: runQuery.initialResults.rows[0]
+        ? toRun(runQuery.initialResults.rows[0])
+        : null,
+      events: eventQuery.initialResults.rows.map(toRunEvent),
+    };
+    let unsubscribePromise: Promise<void> | null = null;
+
+    return {
+      initialSnapshot,
+      unsubscribe: () => {
+        unsubscribePromise ??= (async () => {
+          active = false;
+          await Promise.all([
+            runQuery.unsubscribe(),
+            eventQuery.unsubscribe(),
+          ]);
+        })();
+        return unsubscribePromise;
+      },
+    };
+  }
+}
diff --git a/frontend/src/services/run-trace-api.ts b/frontend/src/services/run-trace-api.ts
new file mode 100644
index 0000000..d3c5495
